  1	package loja.infra;
  2	
  3	import java.time.Instant;
  4	import java.time.LocalDateTime;
  5	import java.time.ZoneOffset;
  6	import java.util.Arrays;
  7	import java.util.List;
  8	import java.util.Optional;
  9	
 10	import org.springframework.jdbc.core.simple.JdbcClient;
 11	import org.springframework.stereotype.Repository;
 12	import tools.jackson.databind.ObjectMapper;
 13	
 14	import loja.dominio.ItemPedido;
 15	import loja.dominio.Pedido;
 16	import loja.dominio.Resumo;
 17	import loja.dominio.Situacao;
 18	
 19	@Repository
 20	public class PedidoRepository {
 21	
 22	    private final JdbcClient jdbc;
 23	    private final ObjectMapper mapper;
 24	
 25	    public PedidoRepository(JdbcClient jdbc, ObjectMapper mapper) {
 26	        this.jdbc = jdbc;
 27	        this.mapper = mapper;
 28	    }
 29	
 30	    public void inserir(Pedido p) {
 31	        jdbc.sql("INSERT INTO pedido (id, cpf, email, situacao, criado_em, resumo) VALUES (?,?,?,?,?,?)")
 32	                .params(p.id(), p.cpf(), p.email(), p.situacao().name(),
 33	                        LocalDateTime.ofInstant(p.criadoEm(), ZoneOffset.UTC), mapper.writeValueAsString(p.resumo()))
 34	                .update();
 35	        int pos = 0;
 36	        for (ItemPedido i : p.itens()) {
 37	            jdbc.sql("INSERT INTO pedido_item (pedido_id, posicao, sku, quantidade) VALUES (?,?,?,?)")
 38	                    .params(p.id(), pos++, i.sku(), i.quantidade()).update();
 39	        }
 40	    }
 41	
 42	    public Optional<Pedido> buscar(String id) {
 43	        return buscar(id, false);
 44	    }
 45	
 46	
 47	    public Optional<Pedido> buscarParaAtualizar(String id) {
 48	        return buscar(id, true);
 49	    }
 50	
 51	    private Optional<Pedido> buscar(String id, boolean travar) {
 52	        String sql = "SELECT * FROM pedido WHERE id = ?" + (travar ? " FOR UPDATE" : "");
 53	        return jdbc.sql(sql).param(id).query((rs, n) -> {
 54	            Instant criado = rs.getObject("criado_em", LocalDateTime.class).toInstant(ZoneOffset.UTC);
 55	            return new Pedido(rs.getString("id"), rs.getString("cpf"), rs.getString("email"),
 56	                    Situacao.valueOf(rs.getString("situacao")), criado,
 57	                    mapper.readValue(rs.getString("resumo"), Resumo.class), List.of(),
 58	                    rs.getString("codigo_rastreio"), rs.getString("id_transacao"));
 59	        }).optional().map(p -> new Pedido(p.id(), p.cpf(), p.email(), p.situacao(), p.criadoEm(), p.resumo(),
 60	                itens(p.id()), p.codigoRastreio(), p.idTransacao()));
 61	    }
 62	
 63	    private List<ItemPedido> itens(String id) {
 64	        return jdbc.sql("SELECT sku, quantidade FROM pedido_item WHERE pedido_id = ? ORDER BY posicao").param(id)
 65	                .query((rs, n) -> new ItemPedido(rs.getString(1), rs.getInt(2))).list();
 66	    }
 67	
 68	    public void atualizarSituacao(String id, Situacao situacao) {
 69	        jdbc.sql("UPDATE pedido SET situacao = ? WHERE id = ?").params(situacao.name(), id).update();
 70	    }
 71	
 72	    public void registrarPagamento(String id, String idTransacao) {
 73	        jdbc.sql("UPDATE pedido SET situacao = ?, id_transacao = ? WHERE id = ?")
 74	                .params(Situacao.PAGO.name(), idTransacao, id).update();
 75	    }
 76	
 77	    public void registrarEnvio(String id, String codigoRastreio) {
 78	        jdbc.sql("UPDATE pedido SET situacao = ?, codigo_rastreio = ? WHERE id = ?")
 79	                .params(Situacao.ENVIADO.name(), codigoRastreio, id).update();
 80	    }
 81	
 82	
 83	    public boolean cpfTemPedidoPago(String cpf) {
 84	        List<String> situacoes = Arrays.stream(Situacao.values()).filter(Situacao::pagoEAtivo).map(Enum::name)
 85	                .toList();
 86	        String marcas = String.join(",", situacoes.stream().map(s -> "?").toList());
 87	        return jdbc.sql("SELECT COUNT(*) FROM pedido WHERE cpf = ? AND situacao IN (" + marcas + ")")
 88	                .params(concat(cpf, situacoes)).query(Long.class).single() > 0;
 89	    }
 90	
 91	    private static List<Object> concat(String cpf, List<String> situacoes) {
 92	        List<Object> l = new java.util.ArrayList<>();
 93	        l.add(cpf);
 94	        l.addAll(situacoes);
 95	        return l;
 96	    }
 97	}
 98	package loja.infra;
 99	
100	import java.math.BigDecimal;
101	import java.util.Collection;
102	import java.util.HashMap;
103	import java.util.List;
104	import java.util.Map;
105	import java.util.Optional;
106	
107	import org.springframework.jdbc.core.simple.JdbcClient;
108	import org.springframework.stereotype.Repository;
109	
110	import loja.dominio.Produto;
111	
112	@Repository
113	public class ProdutoRepository {
114	
115	    private final JdbcClient jdbc;
116	
117	    public ProdutoRepository(JdbcClient jdbc) {
118	        this.jdbc = jdbc;
119	    }
120	
121	    public Optional<Produto> buscar(String sku) {
122	        return jdbc.sql("SELECT * FROM produto WHERE sku = ?").param(sku)
123	                .query((rs, n) -> new Produto(rs.getString("sku"), rs.getString("nome"), rs.getBigDecimal("preco"),
124	                        rs.getBigDecimal("peso_kg"), rs.getInt("estoque"), rs.getBoolean("fora_de_linha")))
125	                .optional();
126	    }
127	
128	    public Map<String, Produto> buscarVarios(Collection<String> skus) {
129	        Map<String, Produto> mapa = new HashMap<>();
130	        for (String sku : skus) {
131	            buscar(sku).ifPresent(p -> mapa.put(sku, p));
132	        }
133	        return mapa;
134	    }
135	
136	
137	    public boolean baixarEstoque(String sku, int quantidade) {
138	        return jdbc.sql("UPDATE produto SET estoque = estoque - ? WHERE sku = ? AND estoque >= ?")
139	                .params(quantidade, sku, quantidade).update() == 1;
140	    }
141	
142	    public void reporEstoque(String sku, int quantidade) {
143	        jdbc.sql("UPDATE produto SET estoque = estoque + ? WHERE sku = ?").params(quantidade, sku).update();
144	    }
145	
146	
147	    public void semear(List<Produto> produtos) {
148	        for (Produto p : produtos) {
149	            if (buscar(p.sku()).isEmpty()) {
150	                jdbc.sql("INSERT INTO produto (sku, nome, preco, peso_kg, estoque, fora_de_linha) VALUES (?,?,?,?,?,?)")
151	                        .params(p.sku(), p.nome(), p.preco(), p.pesoKg(), p.estoque(), p.foraDeLinha()).update();
152	            }
153	        }
154	    }
155	
156	    public static Produto produto(String sku, String nome, String preco, String peso, int estoque, boolean fora) {
157	        return new Produto(sku, nome, new BigDecimal(preco), new BigDecimal(peso), estoque, fora);
158	    }
159	}
160	package loja.infra;
161	
162	import java.math.BigDecimal;
163	import java.util.Optional;
164	
165	import org.springframework.jdbc.core.simple.JdbcClient;
166	import org.springframework.stereotype.Repository;
167	
168	import loja.dominio.Dinheiro;
169	
170	@Repository
171	public class ClienteRepository {
172	
173	    private final JdbcClient jdbc;
174	
175	    public ClienteRepository(JdbcClient jdbc) {
176	        this.jdbc = jdbc;
177	    }
178	
179	    public void criarSeNaoExiste(String cpf, String email) {
180	        jdbc.sql("INSERT INTO cliente (cpf, email, saldo_credito) SELECT CAST(? AS VARCHAR), CAST(? AS VARCHAR), 0"
181	                + " WHERE NOT EXISTS (SELECT 1 FROM cliente WHERE cpf = ?)")
182	                .params(cpf, email, cpf).update();
183	    }
184	
185	    public Optional<BigDecimal> saldo(String cpf) {
186	        return jdbc.sql("SELECT saldo_credito FROM cliente WHERE cpf = ?").param(cpf)
187	                .query((rs, n) -> Dinheiro.arredondar(rs.getBigDecimal(1))).optional();
188	    }
